//! The shared pricing fixtures, `fixtures/pricing/*.json`.
//!
//! The expected values in those files were computed by `reference.py` from the
//! formula as written, in USD with exact rationals — not by this crate. A
//! fixture that agreed only because it was generated by the code under test
//! would prove nothing. The Python and SQL parity tests read the same files.

#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects
)]

use f2z_ai_proto::Usage;
use f2z_ai_proto::pricing::{Bps, Charge, Cost, ModelPrices, price_2z, price_cost};
use serde_json::Value;

fn load(name: &str) -> Vec<Value> {
    let path = format!("{}/fixtures/pricing/{name}", env!("CARGO_MANIFEST_DIR"));
    let text = std::fs::read_to_string(&path).unwrap();
    let doc: Value = serde_json::from_str(&text).unwrap();
    assert_eq!(doc["schema"], 1, "{path}: unknown fixture schema");
    let cases = doc["cases"].as_array().unwrap().clone();
    assert!(
        !cases.is_empty(),
        "{path}: no cases — an empty fixture file passes vacuously"
    );
    cases
}

fn charge(expected: &Value) -> Charge {
    Charge {
        total_milli: expected["total_milli"].as_u64().unwrap(),
        provider_milli: expected["provider_milli"].as_u64().unwrap(),
        developer_milli: expected["developer_milli"].as_u64().unwrap(),
        platform_milli: expected["platform_milli"].as_u64().unwrap(),
    }
}

fn bps(v: &Value) -> Bps {
    Bps(u32::try_from(v.as_u64().unwrap()).unwrap())
}

#[test]
fn every_cost_fixture_prices_exactly() {
    let cases = load("worked_examples.json");
    for case in &cases {
        let name = case["name"].as_str().unwrap();
        let input = &case["input"];
        let got = price_cost(
            Cost::from_nusd(input["cost_nusd"].as_u64().unwrap()),
            bps(&input["platform_margin_bps"]),
            bps(&input["dev_markup_bps"]),
            input["min_charge_2z"].as_u64().unwrap(),
        )
        .unwrap();
        assert_eq!(got, charge(&case["expected"]), "fixture {name}");
    }
}

#[test]
fn the_required_worked_example_is_pinned() {
    // "$0.021 cost at 0% margin → 3 2Z" must stay in the shared file, not only
    // in a Rust unit test, because the Python and SQL sides read the file.
    let cases = load("worked_examples.json");
    let case = cases
        .iter()
        .find(|c| {
            c["input"]["cost_nusd"] == 21_000_000
                && c["input"]["platform_margin_bps"] == 0
                && c["input"]["dev_markup_bps"] == 0
        })
        .expect("the $0.021 @ 0% worked example is missing from the fixtures");
    assert_eq!(case["expected"]["total_milli"], 3_000);
}

#[test]
fn every_usage_fixture_prices_exactly() {
    let cases = load("from_usage.json");
    for case in &cases {
        let name = case["name"].as_str().unwrap();
        let input = &case["input"];
        let usage: Usage = serde_json::from_value(input["usage"].clone()).unwrap();
        let prices: ModelPrices = serde_json::from_value(input["prices"].clone()).unwrap();
        let expected = &case["expected"];

        let cost = Cost::of_usage(&usage, &prices).unwrap();
        assert_eq!(
            cost.femto_usd(),
            u128::from(expected["cost_femto_usd"].as_u64().unwrap()),
            "fixture {name}: exact cost"
        );
        assert_eq!(
            cost.ceil_nusd().unwrap(),
            expected["cost_nusd_ceil"].as_u64().unwrap(),
            "fixture {name}: cost handed to settle"
        );
        let got = price_2z(
            &usage,
            &prices,
            bps(&input["platform_margin_bps"]),
            bps(&input["dev_markup_bps"]),
            input["min_charge_2z"].as_u64().unwrap(),
        )
        .unwrap();
        assert_eq!(got, charge(expected), "fixture {name}");
    }
}
